window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-838fedb05f557a3e"]={"versions": [{"id": "FIG-838fedb05f557a3e", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell) zur Modellierung von C++-Implementierungsdatentypen im Kontext der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Dargestellt wird die Struktur eines assoziativen Arrays (<code>ASSOCIATIVE_MAP</code>) unter Verwendung von C++-Template-Argumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>MyVariant :CppImplementationDataType</strong>: Wurzelinstanz des Datentyps mit Attribut <code>category = ASSOCIATIVE_MAP</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (zwei anonyme Instanzen): Über Kompositionsbeziehungen mit Rollennamen <code>+templateArgument</code> an <code>MyVariant</code> gebunden.</li>\n<li><strong>uint16 : CppImplementationDataType</strong>: Zielinstanz für den Schlüsseldatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des ersten Template-Arguments.</li>\n<li><strong>uint8 : CppImplementationDataType</strong>: Zielinstanz für den Wertdatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des zweiten Template-Arguments.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanz- und Strukturmodell. Es wird kein dynamischer Ablauf oder Nachrichtenaustausch dargestellt; die Beziehungen definieren die Deklarationshierarchie und Typauflösung zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein Datentyp der Kategorie <code>ASSOCIATIVE_MAP</code> (semantisch äquivalent zu <code>std::map</code>) aggregiert geordnet mindestens zwei <code>CppTemplateArgument</code>-Elemente: Das erste Argument repräsentiert den Schlüssel (<code>key</code>), das zweite den Wert (<code>value</code>). Beide müssen über die Assoziation <code>+templateType</code> auf konkrete <code>CppImplementationDataType</code>-Definitionen verweisen.</p>"}, {"id": "FIG-0a431c65deeb49f2", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell) zur Modellierung von C++-Implementierungsdatentypen im Kontext der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Dargestellt wird die Struktur eines assoziativen Arrays (<code>ASSOCIATIVE_MAP</code>) unter Verwendung von C++-Template-Argumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>MyVariant: StdCppImplementationDataType</strong>: Wurzelinstanz des Datentyps mit Attribut <code>category = ASSOCIATIVE_MAP</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (zwei anonyme Instanzen): Über Kompositionsbeziehungen mit Rollennamen <code>+templateArgument</code> an <code>MyVariant</code> gebunden.</li>\n<li><strong>uint16_t: StdCppImplementationDataType</strong>: Zielinstanz für den Schlüsseldatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des ersten Template-Arguments.</li>\n<li><strong>uint8_t: StdCppImplementationDataType</strong>: Zielinstanz für den Wertdatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des zweiten Template-Arguments.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanz- und Strukturmodell. Es wird kein dynamischer Ablauf oder Nachrichtenaustausch dargestellt; die Beziehungen definieren die Deklarationshierarchie und Typauflösung zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein Datentyp der Kategorie <code>ASSOCIATIVE_MAP</code> aggregiert geordnet mindestens zwei <code>CppTemplateArgument</code>-Elemente für Schlüssel und Wert. Die referenzierten Datentypen sind Instanzen von <code>StdCppImplementationDataType</code> mit C99/C++-Standardtypen (<code>uint16_t</code>, <code>uint8_t</code>) und <code>category = VALUE</code>.</p>"}, {"id": "FIG-2cc2a05c38cbcd81", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell) zur Modellierung von C++-Implementierungsdatentypen im Kontext der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Dargestellt wird die Struktur eines assoziativen Arrays (<code>ASSOCIATIVE_MAP</code>) unter Verwendung von C++-Template-Argumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>MyVariant: StdCppImplementationDataType</strong>: Wurzelinstanz des Datentyps mit Attribut <code>category = ASSOCIATIVE_MAP</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (zwei anonyme Instanzen): Über Kompositionsbeziehungen mit Rollennamen <code>+templateArgument</code> an <code>MyVariant</code> gebunden.</li>\n<li><strong>uint16_t: StdCppImplementationDataType</strong>: Zielinstanz für den Schlüsseldatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des ersten Template-Arguments.</li>\n<li><strong>uint8_t: StdCppImplementationDataType</strong>: Zielinstanz für den Wertdatentyp mit <code>category = VALUE</code>, referenziert über die gerichtete Assoziation <code>+templateType</code> des zweiten Template-Arguments.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanz- und Strukturmodell. Es wird kein dynamischer Ablauf oder Nachrichtenaustausch dargestellt; die Beziehungen definieren die Deklarationshierarchie und Typauflösung zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein Datentyp der Kategorie <code>ASSOCIATIVE_MAP</code> aggregiert geordnet mindestens zwei <code>CppTemplateArgument</code>-Elemente für Schlüssel und Wert. Die referenzierten Datentypen sind Instanzen von <code>StdCppImplementationDataType</code> mit C99/C++-Standardtypen (<code>uint16_t</code>, <code>uint8_t</code>) und <code>category = VALUE</code>.</p>"}, {"id": "FIG-6d571477c3ee7d9d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell) zur Modellierung von C++-Implementierungsdatentypen im Kontext der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Dargestellt wird die Struktur eines assoziativen Arrays (<code>ASSOCIATIVE_MAP</code>) unter Verwendung von C++-Template-Argumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>MyVariant: StdCppImplementationDataType</strong>: Wurzelinstanz des Datentyps mit Attribut <code>category = ASSOCIATIVE_MAP</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (linke Instanz): Kompositionsrolle <code>+templateArgument</code> an <code>MyVariant</code>, explizit typisiert mit Attribut <code>category = ASSOC_MAP_KEY</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (rechte Instanz): Kompositionsrolle <code>+templateArgument</code> an <code>MyVariant</code>, explizit typisiert mit Attribut <code>category = ASSOC_MAP_VALUE</code>.</li>\n<li><strong>uint16_t: StdCppImplementationDataType</strong>: Zielinstanz mit <code>category = VALUE</code>, über Assoziation <code>+templateType</code> an das Schlüssel-Template-Argument gebunden.</li>\n<li><strong>uint8_t: StdCppImplementationDataType</strong>: Zielinstanz mit <code>category = VALUE</code>, über Assoziation <code>+templateType</code> an das Wert-Template-Argument gebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanz- und Strukturmodell. Es wird kein dynamischer Ablauf oder Nachrichtenaustausch dargestellt; die Beziehungen definieren die Deklarationshierarchie und Typauflösung zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Rollen der Template-Argumente für ein assoziatives Mapping werden über das Attribut <code>category</code> an den <code>CppTemplateArgument</code>-Instanzen formal festgelegt: <code>ASSOC_MAP_KEY</code> für den Kartenschlüssel und <code>ASSOC_MAP_VALUE</code> für den zugeordneten Wert. Beide verweisen über <code>+templateType</code> auf die zugrundeliegenden <code>StdCppImplementationDataType</code>-Objekte.</p>"}, {"id": "FIG-d4a7f545d126fe0a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzmodell) zur Modellierung von C++-Implementierungsdatentypen im Kontext der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Dargestellt wird die Struktur eines assoziativen Arrays (<code>ASSOCIATIVE_MAP</code>) unter Verwendung von C++-Template-Argumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>MyVariant: StdCppImplementationDataType</strong>: Wurzelinstanz des Datentyps mit Attribut <code>category = ASSOCIATIVE_MAP</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (linke Instanz): Kompositionsrolle <code>+templateArgument</code> an <code>MyVariant</code>, explizit typisiert mit Attribut <code>category = ASSOC_MAP_KEY</code>.</li>\n<li><strong>:CppTemplateArgument</strong> (rechte Instanz): Kompositionsrolle <code>+templateArgument</code> an <code>MyVariant</code>, explizit typisiert mit Attribut <code>category = ASSOC_MAP_VALUE</code>.</li>\n<li><strong>uint16_t: StdCppImplementationDataType</strong>: Zielinstanz mit <code>category = VALUE</code>, über Assoziation <code>+templateType</code> an das Schlüssel-Template-Argument gebunden.</li>\n<li><strong>uint8_t: StdCppImplementationDataType</strong>: Zielinstanz mit <code>category = VALUE</code>, über Assoziation <code>+templateType</code> an das Wert-Template-Argument gebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanz- und Strukturmodell. Es wird kein dynamischer Ablauf oder Nachrichtenaustausch dargestellt; die Beziehungen definieren die Deklarationshierarchie und Typauflösung zur Entwurfs- bzw. Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Rollen der Template-Argumente für ein assoziatives Mapping werden über das Attribut <code>category</code> an den <code>CppTemplateArgument</code>-Instanzen formal festgelegt: <code>ASSOC_MAP_KEY</code> für den Kartenschlüssel und <code>ASSOC_MAP_VALUE</code> für den zugeordneten Wert. Beide verweisen über <code>+templateType</code> auf die zugrundeliegenden <code>StdCppImplementationDataType</code>-Objekte.</p>"}], "trans": [{"from": "FIG-838fedb05f557a3e", "to": "FIG-0a431c65deeb49f2", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Das übergeordnete Datentyp-Objekt <code>MyVariant</code> wechselt den Typ von <code>:CppImplementationDataType</code> zu <code>:StdCppImplementationDataType</code>.</li>\n<li>Die referenzierten Zieltypen der Template-Argumente wechseln von <code>uint16 : CppImplementationDataType</code> zu <code>uint16_t: StdCppImplementationDataType</code> und von <code>uint8 : CppImplementationDataType</code> zu <code>uint8_t: StdCppImplementationDataType</code>.</li>\n</ul>"}, {"from": "FIG-0a431c65deeb49f2", "to": "FIG-2cc2a05c38cbcd81", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2cc2a05c38cbcd81", "to": "FIG-6d571477c3ee7d9d", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die beiden anonymen <code>:CppTemplateArgument</code>-Instanzen erhalten jeweils ein Attribut <code>category</code>: der linke Schlüssel-Parameter wird als <code>category = ASSOC_MAP_KEY</code> typisiert, der rechte Wert-Parameter als <code>category = ASSOC_MAP_VALUE</code>.</li>\n<li>Die Objektnamen <code>:CppTemplateArgument</code> sind unterstrichen dargestellt.</li>\n</ul>"}, {"from": "FIG-6d571477c3ee7d9d", "to": "FIG-d4a7f545d126fe0a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
